\ENDFOR
\STATE Compute $\mathbf{O}_i = \mathrm{diag}(\ell_i)^{-1} \mathbf{O}_i$ and $L_i = m_i + \log(\ell_i)$.
\STATE Write $\mathbf{O}_i$ and $L_i$ to HBM as the $i$th block of $\mathbf{O}$ and $L$.
\ENDIF
\end{algorithmic}
\end{algorithm}

