\label{sec:algo_ws}

\paragraph{Warp-specialization}
As with \textsc{FlashAttention-2}, the forward pass of \textsc{FlashAttention-3} is embarrassingly parallel in the batch size, number of heads, and query sequence length. Thus, it will suffice to give a CTA-level view of the algorithm, which operates on a tile $\mathbf{Q}_i$ of the query matrix to compute the corresponding tile $\mathbf{O}_i$ of the output. To simplify the description, we first give the warp-specialization scheme with a circular SMEM buffer that does \emph{not} have in addition the GEMM-softmax overlapping. Let $d$ be the head dimension, $N$ the sequence length, and fix a query block size $B_r$ to divide $\mathbf{Q}$ into $T_r = \lceil \frac{N}{B_r} \rceil$ blocks $\mathbf{Q}_1, .., \mathbf{Q}_{T_r}$.

\begin{algorithm}[H]
    \caption{\small\label{alg:flash3_wgmma_ws_only}\textsc{FlashAttention-3} forward pass \textbf{without} intra-consumer overlapping -- CTA view}
    \begin{algorithmic}[1]
\REQUIRE Matrices $\mathbf{Q}_i \in \mathbb{R}^{B_r \times d}$ and $\mathbf{K}, \mathbf{V} \in \mathbb{R}^{N \times d}$ in HBM, key block size $B_c$ with $T_c = \lceil \frac{N}{B_c} \rceil$.
\STATE Initialize pipeline object to manage barrier synchronization with $s$-stage circular SMEM buffer.
\IF {in producer warpgroup}
\STATE Deallocate predetermined number of registers.
\STATE Issue load $\mathbf{Q}_i$ from HBM to shared memory.
\STATE Upon completion, commit to notify consumer of the load of $\mathbf{Q}_i$.
\FOR{$0 \le j < T_c$}
    \STATE Wait for the $(j\,\%\,s)$th stage of the buffer to be consumed.
    \STATE Issue loads of $\mathbf{K}_j, \mathbf{V}_j$ from HBM to shared memory at the $(j\,\%\,s)$th stage of the buffer.
    \STATE Upon completion, commit to notify consumers of the loads of $\mathbf{K}_j, \mathbf{V}_j$.
\ENDFOR
\ELSE \STATE Reallocate predetermined number of registers as function of number of consumer warps.
\STATE On-chip, initialize $\mathbf{O}_i = (0) \in \mathbb{R}^{B_r \times d}$ and $\ell_i, m_i = (0), (-\infty) \in \mathbb{R}^{B_r}$.
\STATE Wait for $\mathbf{Q}_i$ to be loaded in shared memory.
\FOR{$0 \le j < T_c$}
\STATE Wait for $\mathbf{K}_j$ to be loaded in shared memory.
\STATE Compute $\mathbf{S}_i^{(j)} = \mathbf{Q}_i \mathbf{K}_j^T$ (SS-GEMM). Commit and wait. \label{alg:ws_only_gemm1}
\STATE Store $m_i^{\mathrm{old}} = m_i$ and compute $m_i = \mathrm{max}(m_i^{\mathrm{old}}, \mathrm{rowmax}(\mathbf{S}_i^{(j)}))$. \label{code-ws:softmax_start}
\STATE Compute $\widetilde{\mathbf{P}}_i^{(j)} = \mathrm{exp}(\mathbf{S}_i^{(j)} - m_i)$ and $\ell_i = \mathrm{exp}(m_i^{\mathrm{old}} - m_i) \ell_i + \mathrm{rowsum}(\widetilde{\mathbf{P}}_i^{(j)})$. \label{code-ws:softmax_end}
\STATE Wait for $\mathbf{V}_j$ to be loaded in shared memory.
\STATE Compute $\mathbf{O}_i = \mathrm{diag}(\mathrm{exp}(m_i^{\mathrm{old}} - m_i))^{-1} \mathbf{O}_i + \widetilde{\mathbf{P}}_i^{(j)} \mathbf{V}_j$ (RS-GEMM). Commit and wait. \label{alg:ws_only_gemm2}
\STATE Release the $(j\,\%\,s)$th stage of the buffer for the producer.
\ENDFOR
\STATE Compute $\mathbf{O}_i = \mathrm{diag}(\ell_i)^{-1} \mathbf{O}_i$ and $L_i = m_i + \log(\ell_i)$.
\STATE Write $\mathbf{O}_i$ and $L_i$ to HBM as the $i$th block of $\mathbf{O}$ and $L$.
\ENDIF
\end{algorithmic}
\end{algorithm}

For our implementation of \cref{alg:flash3_wgmma_ws_only} on Hopper, we use \verb|setmaxnreg| for (de)allocations, TMA for loads of $\mathbf{Q}_i$ and $\{ \mathbf{K}_j, \mathbf{V}_j \}_{0 \leq j < T_c}$, and WGMMA to execute the GEMMs in the consumer mainloop, with the SS or RS prefix indicating whether the first operand is sourced from shared memory or register file. For interpreting the execution flow of \cref{alg:flash3_wgmma_ws_only}, note that issuing TMA loads does not stall on the completion of other loads due to asynchrony. Moreover, in the producer mainloop, no waits will be issued for the first $s$ iterations as the buffer gets filled.

